/**
 * The server-computed part of an import's Review and publish summary (GET /imports/:id/lookup `summary`), so the Web never
 * decides on its own what Publish waits for: whether the import appends, which work Publish waits for, whether a new Album's
 * credit rests only on a placeholder, how many identity rows still need an answer, whether this server can run metadata
 * lookup, each shown Luna suggestion's tick state and the analysis budget the Analyze confirmation shows. For a saved append to an
 * Album with an expected tracklist, until its publication is complete, it also lists the target's rows, which of them current
 * members fill, each file's duration and whether it is appended, and the one-step numbering from that tracklist
 * (importAppendTracklist); the Web places the shown files on those rows. Lookup answers stay in the lookup view (`needsAnswer`). The publish transaction rechecks all of it, the upload
 * wait with importUploadsWaiting; the rows are information only and never hold Publish. Pure. Owner rules: docs/business-rules.md
 * (Administrator Album Imports, Review and publish summary, appending and Luna bullets).
 */
import { ADMIN_IMPORT_LIMITS, isLookupCoverSlot } from './adminImportContract';
import { boundArtistDecision, boundLabelDecision, type ImportDecisionV2, type ImportDraftOrigins, type ImportDraftV2 } from './adminImportDraft';
import { importDraftV2View, importProjectV2View, legacyManifestView } from './adminImportDraftCompat';
import { lunaTick, shownPendingSuggestions, type LunaTick } from './adminImportLunaTicks';
import { importUploadSettled, type ImportAsset } from './adminImportMediaTypes';
import { lookupCoverStagingActive } from './adminImportCoverAutomation';
import type { AdminImportDocument } from './adminImportService';
import { importAssetDurationEvidence, importTagsV2View } from './adminImportTags';
import { draftWithinSizeLimit, importAutomationMarkers, originOf } from './adminImportValueState';
import { METADATA_LOOKUP_LIMITS } from '../lookup/lookupContract';
import { isPlaceholderCredit } from '../lookup/lookupIdentifiers';
import { lookupDurationMs, lookupForcedPairs } from '../lookup/lookupSubset';
import { isBlockingLookupState, type MetadataLookupRecord } from '../lookup/metadataLookupRecord';
import { expectedTrackPosition, expectedTrackRows, storedExpectedTracklist } from '../../services/catalog/albumExpectedTracklist';

export type ImportSummaryView = {
    /** An explicit Album reuse: the draft's Album values, entries, label, cover and Album lookup conflicts are not applied. */
    append: boolean;
    /** `cover`: the applied lookup candidate's front artwork is being staged (queued or running within its grant). */
    waiting: { uploads: boolean; lookup: boolean; cover: boolean; analysis: boolean };
    /** A new Album without a primary Artist entry whose files or applied lookup release credit only a placeholder. */
    placeholderOnly: boolean;
    luna: { id: string; tick: LunaTick }[];
    /** What is left: analysis runs and provider calls for this project, and provider calls today across the deployment. */
    analysis: { runs: number; attempts: number; daily: number };
    /** Whether this server can run metadata lookup at all; without it the summary offers Luna and no lookup step. */
    lookupAvailable: boolean;
    /** Identity rows of the saved draft that neither a saved decision nor a preselection answers (importIdentityAnswers). */
    identityAnswers: number;
    /**
     * Present only for a saved append to a ready Album with a valid expected tracklist whose publication is not complete: its rows,
     * the files and the numbering. Once complete, the import's own new members fill the rows, so none is listed.
     */
    appendTracklist?: ImportAppendTracklist;
};
/** What the summary read found for the saved append target, read in the same snapshot: its stored tracklist and its members' numbers. */
export type ImportAppendTarget = { albumId: string; tracklist: unknown; members: readonly { discNumber: unknown; trackNumber: unknown }[] };
export type ImportAppendTracklist = {
    albumId: string;
    /** The metadata lookup duration tolerance; the Web adds 1000 ms for a legacy whole-second duration. */
    durationToleranceMs: number;
    /** Rows in Disc then Track Number order. `filled`: a member of any lifecycle state or visibility sits at its position. */
    rows: { discNumber: number; trackNumber: number; title: string; durationMs: number | null; filled: boolean }[];
    /** One entry per manifest file, in manifest order. `appended`: neither its saved track decision nor, without one, its preselection skips or reuses it. */
    files: { slotId: string; durationMs: number | null; durationPrecisionMs: 0 | 1000; appended: boolean }[];
    /** The one-step numbering, from the pairs every largest pairing of the saved draft shares. `title` is null when the file keeps its own. */
    numbering: { slotId: string; discNumber: number; trackNumber: number; title: string | null }[];
};
/**
 * What the summary reads beside the project: the time it is read at, provider calls used today, the lookup configuration, the
 * identity rows left to answer and, for a saved append, its target (readAppendTarget) and the identity preselections.
 */
export type ImportSummaryContext = { now: Date; dailyAttemptsUsed: number; lookupAvailable: boolean; identityAnswers: number;
    appendTarget?: ImportAppendTarget | null; preselections?: readonly ImportDecisionV2[] };

const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const left = (limit: number, used: unknown) => Math.max(0, limit - (Number.isSafeInteger(used) && (used as number) > 0 ? used as number : 0));

/**
 * Whether every manifest file has confirmed version-2 tag evidence naming album-level credits (album artists, else artists) and
 * all of them are placeholders such as Various Artists.
 */
function filesCreditOnlyPlaceholders(files: readonly { slotId: string }[], doc: AdminImportDocument): boolean {
    const assets = doc.media?.assets ?? [];
    const credits = files.map(file => {
        const tags = importTagsV2View(assets.find(asset => asset.slotId === file.slotId && asset.state === 'ready')?.tags);
        return tags?.version === 2 ? (tags.albumArtists.length ? tags.albumArtists : tags.artists) : [];
    });
    return files.length > 0 && credits.every(names => names.length > 0 && names.every(name => isPlaceholderCredit(name)));
}

/**
 * Whether Publish waits for uploads: any staged upload (a file or a cover) is still in flight, pending with a PUT that can
 * still land (importUploadSettled), or a manifest file whose track needs its bytes lacks a confirmed upload. A track decided
 * `skip` is never published and one decided `reuse` keeps the existing member's media, so neither needs its file. A lookup cover
 * never counts: its staging holds Publish only while queued or running within its grant (lookupCoverStagingActive), and a failed
 * one never waits, even while its admitted record has not settled. The summary passes the saved decisions; the publish
 * transaction its frozen ones, preselections included.
 */
export function importUploadsWaiting(doc: Pick<AdminImportDocument, 'manifest' | 'media'>, decisions: readonly unknown[], now: Date): boolean {
    const files = legacyManifestView(doc.manifest).files, assets = doc.media?.assets ?? [];
    const unneeded = (slotId: string) => decisions.some(decision => isRecord(decision) && decision.scope === 'track' && decision.slotId === slotId
        && (decision.action === 'skip' || decision.action === 'reuse'));
    return assets.some(asset => asset.state === 'pending' && !isLookupCoverSlot(asset.slotId) && !importUploadSettled(asset, now))
        || files.some(file => !unneeded(file.slotId) && !assets.some(asset => asset.slotId === file.slotId && asset.state === 'ready'));
}

/**
 * How many identity rows of `draft` neither an explicit decision nor a preselection answers with a reuse (one that replaces a
 * MusicBrainz ID included; an exact-ID match is preselected as reuse) or a new record, as the
 * publication confirmation counts the rows that need a decision: the Album, each track that is not skipped and, unless the
 * Album is reused (an append applies neither), each Artist entry and the label.
 */
export function importIdentityAnswers(draft: ImportDraftV2, decisions: readonly ImportDecisionV2[], preselections: readonly ImportDecisionV2[]): number {
    const all = [...decisions, ...preselections], album = all.find(decision => decision.scope === 'album');
    const tracks = draft.tracks.map(track => all.find(decision => decision.scope === 'track' && decision.slotId === track.slotId)).filter(decision => decision?.action !== 'skip');
    const rows = [album, ...tracks, ...album?.action === 'reuse' ? [] : [...draft.album.artists.map(entry => boundArtistDecision(all, entry)),
        ...draft.album.label ? [boundLabelDecision(all, draft.album.label)] : []]];
    return rows.filter(decision => decision?.action !== 'reuse' && decision?.action !== 'replace' && decision?.action !== 'create-distinct').length;
}

const positionKey = (position: { discNumber: number; trackNumber: number }) => `${position.discNumber}:${position.trackNumber}`;

/**
 * The rows of a saved append's target and how the saved draft's files meet them, or null when `target` is not the saved Album
 * reuse (`albumId`) or holds no valid expected tracklist. A row is filled by any member at its position (a missing Disc Number
 * counts as disc 1). A file is appended unless its saved track decision, else its preselection, skips or reuses it. The numbering
 * pairs the appended files with the missing-file rows, as members pair with a release: a file whose Disc and Track Numbers are
 * both the administrator's own is left out and its position taken, numbers lookup wrote do not constrain, and file-tag numbers
 * and durations do. Each file every largest pairing places on one row takes that row's numbers and, when its title is empty or
 * automatic, its title. A file the numbering does not move keeps its position, so no other file is numbered onto it; a file left
 * out for that keeps its own position in turn. None is offered when that would grow the draft past its size cap.
 */
export function importAppendTracklist(input: { draft: ImportDraftV2; origins: ImportDraftOrigins | undefined; lookupPaths: readonly string[]; files: readonly { slotId: string }[];
    assets: readonly ImportAsset[]; decisions: readonly unknown[]; preselections: readonly ImportDecisionV2[]; albumId: string; target: ImportAppendTarget }): ImportAppendTracklist | null {
    const stored = input.target.albumId === input.albumId ? storedExpectedTracklist({ expectedTracklist: input.target.tracklist }) : null;
    if (!stored) return null;
    const members = input.target.members.map((member, index) => ({ id: String(index), discNumber: member.discNumber, trackNumber: member.trackNumber }));
    const rows = expectedTrackRows(stored.rows, members).rows.map(row => ({ discNumber: row.discNumber, trackNumber: row.trackNumber, title: row.title, durationMs: row.durationMs, filled: row.memberIds.length > 0 }));
    const files = input.files.map(file => {
        const asset = input.assets.find(item => item.slotId === file.slotId && item.state === 'ready'), evidence = asset ? importAssetDurationEvidence(asset) : null;
        const known = evidence && lookupDurationMs(evidence.durationMs) !== null && Number.isSafeInteger(evidence.durationMs) ? evidence : null;
        const saved = input.decisions.find((decision): decision is Record<string, unknown> => isRecord(decision) && decision.scope === 'track' && decision.slotId === file.slotId);
        const action = saved ? saved.action : input.preselections.find(decision => decision.scope === 'track' && decision.slotId === file.slotId)?.action;
        return { slotId: file.slotId, durationMs: known?.durationMs ?? null, durationPrecisionMs: known?.durationPrecisionMs ?? 0, appended: action !== 'skip' && action !== 'reuse' };
    });
    const appended = new Map(files.filter(file => file.appended).map(file => [file.slotId, file]));
    const tracks = input.draft.tracks.filter(track => appended.has(track.slotId));
    const path = (slotId: string, field: 'title' | 'discNumber' | 'trackNumber') => `tracks.${slotId}.${field}`;
    const own = (slotId: string, field: 'discNumber' | 'trackNumber') => originOf(input.origins, path(slotId, field)) === 'administrator';
    const fixed = (track: ImportDraftV2['tracks'][number]) => track.discNumber !== null && track.trackNumber !== null && own(track.slotId, 'discNumber') && own(track.slotId, 'trackNumber');
    const taken = new Set(tracks.filter(fixed).flatMap(track => { const position = expectedTrackPosition(track.discNumber, track.trackNumber); return position ? [positionKey(position)] : []; }));
    const slots = rows.filter(row => !row.filled && !taken.has(positionKey(row))).map(row => ({ discNumber: row.discNumber, trackNumber: row.trackNumber, durationMs: row.durationMs }));
    const pairing = tracks.filter(track => !fixed(track)).map(track => ({ slotId: track.slotId,
        discNumber: input.lookupPaths.includes(path(track.slotId, 'discNumber')) ? null : track.discNumber,
        trackNumber: input.lookupPaths.includes(path(track.slotId, 'trackNumber')) ? null : track.trackNumber,
        durationMs: appended.get(track.slotId)!.durationMs, durationPrecisionMs: appended.get(track.slotId)!.durationPrecisionMs }));
    const titles = new Map(rows.map(row => [positionKey(row), row.title]));
    let pairs = lookupForcedPairs(slots, pairing);
    // Each round drops the pairs onto a position an unmoved appended file keeps, until none is left; the list only shrinks.
    for (let dropped = true; dropped;) {
        const kept = new Set(tracks.filter(track => !pairs.some(pair => pair.slotId === track.slotId))
            .flatMap(track => { const position = expectedTrackPosition(track.discNumber, track.trackNumber); return position ? [positionKey(position)] : []; }));
        const remaining = pairs.filter(pair => !kept.has(positionKey(pair)));
        dropped = remaining.length < pairs.length; pairs = remaining;
    }
    let numbering = pairs.map(pair => {
        const track = tracks.find(item => item.slotId === pair.slotId)!;
        const automatic = track.title === '' || originOf(input.origins, path(pair.slotId, 'title')) === 'automatic';
        return { slotId: pair.slotId, discNumber: pair.discNumber, trackNumber: pair.trackNumber, title: automatic ? titles.get(positionKey(pair))! : null };
    });
    const next = structuredClone(input.draft);
    for (const entry of numbering) {
        const track = next.tracks.find(item => item.slotId === entry.slotId)!;
        Object.assign(track, { discNumber: entry.discNumber, trackNumber: entry.trackNumber }, entry.title === null ? {} : { title: entry.title });
    }
    if (!draftWithinSizeLimit(input.draft, next)) numbering = [];
    return { albumId: input.albumId, durationToleranceMs: METADATA_LOOKUP_LIMITS.durationToleranceMs, rows, files, numbering };
}

/**
 * The summary state of `doc` with its lookup record (null before any run) and `context`. Uploads are waited for as
 * importUploadsWaiting says with the saved decisions, lookup while its run is queued, running or retrying automatically (value
 * application shares that step), the lookup cover while its staging is queued or running within its grant (a failed, skipped or
 * expired one never waits), and analysis while it is queued or running. A saved append whose target the context read lists that
 * target's rows (importAppendTracklist) until its publication is complete; the key is absent otherwise, so other summaries keep
 * their shape. A stored manifest in a shape this release does not know reads as its sanitized view, as the editor shows it.
 */
export function importSummaryView(doc: AdminImportDocument, lookup: Partial<MetadataLookupRecord> | null, context: ImportSummaryContext): ImportSummaryView {
    const id = doc._id.toHexString(), manifest = legacyManifestView(doc.manifest);
    const draft = importDraftV2View(doc.draft, manifest, id), origins = importProjectV2View(doc)?.draftOrigins;
    const applied = isRecord(lookup?.applied) ? lookup!.applied : null;
    const markers = importAutomationMarkers(draft, origins, Array.isArray(applied?.values) ? applied!.values : []);
    const tagPaths = new Set<string>(markers.automaticPaths.filter(path => !markers.lookupPaths.includes(path)));
    const decisions = Array.isArray(doc.decisions) ? doc.decisions : [];
    const reuse = (decisions as readonly unknown[]).find((decision): decision is Record<string, unknown> => isRecord(decision) && decision.scope === 'album' && decision.action === 'reuse');
    const append = Boolean(reuse);
    const appliedPlaceholder = Array.isArray(applied?.flagged) && applied!.flagged.some(flag => isRecord(flag) && flag.path === 'album.artists' && flag.reason === 'placeholder');
    const appendTracklist = typeof reuse?.candidateId === 'string' && context.appendTarget && doc.media?.publication?.state !== 'complete' ? importAppendTracklist({ draft, origins,
        lookupPaths: markers.lookupPaths, files: manifest.files, assets: doc.media?.assets ?? [], decisions, preselections: context.preselections ?? [], albumId: reuse.candidateId,
        target: context.appendTarget }) : null;
    return {
        append,
        waiting: {
            uploads: importUploadsWaiting(doc, decisions, context.now),
            lookup: isBlockingLookupState(lookup?.state) || doc.lookupGate?.blocking === true,
            cover: lookupCoverStagingActive(doc.media?.lookupCover, context.now),
            analysis: ['queued', 'running'].includes(doc.analysis?.state)
        },
        placeholderOnly: !append && !draft.album.artists.some(entry => entry.role === 'primary') && (appliedPlaceholder || filesCreditOnlyPlaceholders(manifest.files, doc)),
        luna: shownPendingSuggestions(doc).map(suggestion => ({ id: suggestion.id, tick: lunaTick(draft, origins, suggestion, tagPaths) })),
        analysis: { runs: left(ADMIN_IMPORT_LIMITS.generations, doc.analysis?.generation), attempts: left(ADMIN_IMPORT_LIMITS.attempts, doc.attemptsUsed),
            daily: left(ADMIN_IMPORT_LIMITS.dailyAttempts, context.dailyAttemptsUsed) },
        lookupAvailable: context.lookupAvailable,
        identityAnswers: context.identityAnswers,
        ...appendTracklist ? { appendTracklist } : {}
    };
}
